const PACKAGES = [
  { id: "basic", name: "Basic", price: 150, duration: "2 Hours", features: ["1 Photographer", "15 Edited Photos"] },
  { id: "standard", name: "Standard", price: 350, duration: "4 Hours", features: ["1 Photographer", "40 Edited Photos"] },
  { id: "premium", name: "Premium", price: 700, duration: "Full Day", features: ["2 Photographers", "All Edited Photos"] }
];

// Helper to construct exact public/images path
const getImagePath = (filename) => {
  return process.env.PUBLIC_URL + `/images/${filename}`;
};

export default function App() {
  const [activeTab, setActiveTab] = useState("home");
  const [favorites, setFavorites] = useState(() => {
    const saved = localStorage.getItem("fav_photos");
    return saved ? JSON.parse(saved) : [];
  });

  const [selectedCategory, setSelectedCategory] = useState("All");
  const [activeLightbox, setActiveLightbox] = useState(null);

  useEffect(() => {
    localStorage.setItem("fav_photos", JSON.stringify(favorites));
  }, [favorites]);

  const toggleFavorite = (id) => {
    setFavorites((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  const filteredImages = GALLERY_IMAGES.filter((img) =>
    selectedCategory === "All" || img.category === selectedCategory
  );

  const displayedImages = activeTab === "favorites"
    ? GALLERY_IMAGES.filter((img) => favorites.includes(img.id))
    : filteredImages;

  return (
    <div className="app-container sea-green">
      <nav className="navbar">
        <div className="nav-brand"><span>📷</span> SHUTTER STORIES</div>
        <ul className="nav-links">
          {["home", "gallery", "packages", "favorites"].map((tab) => (
            <li key={tab}>
              <button
                className={activeTab === tab ? "active" : ""}
                onClick={() => setActiveTab(tab)}
              >
                {tab.charAt(0).toUpperCase() + tab.slice(1)} {tab === "favorites" ? `(${favorites.length})` : ""}
              </button>
            </li>
          ))}
        </ul>
      </nav>

      {activeTab === "home" && (
        <section className="hero-section">
          <div className="hero-backdrop">
            <img
              src={getImagePath("hero-bg.jpg")}
              alt="Hero background"
              onError={(e) => {
                e.target.onerror = null;
                // If local hero-bg fails, fallback to online background
                e.target.src = "https://images.unsplash.com/photo-1542038784456-1ea8e935640e?w=1200";
              }}
            />
            <div className="hero-overlay"></div>
          </div>
          <div className="hero-content">
            <h1>Capturing Moments</h1>
            <p>Professional photography services for the stories that matter.</p>
            <button className="btn-primary" onClick={() => setActiveTab("gallery")}>View Portfolio</button>
          </div>
        </section>
      )}

      {(activeTab === "gallery" || activeTab === "favorites") && (
        <section className="gallery-section">
          <h2>{activeTab === "favorites" ? "Your Favorites" : "Portfolio Gallery"}</h2>

          {activeTab !== "favorites" && (
            <div className="filter-bar">
              {CATEGORIES.map((cat) => (
                <button
                  key={cat}
                  className={selectedCategory === cat ? "filter-btn active" : "filter-btn"}
                  onClick={() => setSelectedCategory(cat)}
                >
                  {cat}
                </button>
              ))}
            </div>
          )}

          <div className="gallery-grid">
            {displayedImages.length > 0 ? displayedImages.map((img) => (
              <div className="gallery-card" key={img.id}>
                <div className="img-wrapper">
                  <img
                    src={getImagePath(img.filename)}
                    alt={img.title}
                    onError={(e) => {
                      e.target.onerror = null;
                      e.target.src = img.fallbackSrc;
                    }}
                    onClick={() => setActiveLightbox(img)}
                  />
                </div>
                <div className="card-info">
                  <h4>{img.title}</h4>
                  <button className="fav-btn" onClick={() => toggleFavorite(img.id)}>
                    {favorites.includes(img.id) ? "❤️" : "🤍"}
                  </button>
                </div>
              </div>
            )) : <p className="no-data">No favorites yet.</p>}
          </div>
        </section>
      )}

      {activeTab === "packages" && (
        <section className="packages-section">
          <h2>Pricing Packages</h2>
          <div className="packages-grid">
            {PACKAGES.map((pkg) => (
              <div key={pkg.id} className="package-card">
                <h3>{pkg.name}</h3>
                <p className="price">{pkg.price > 0 ? `$${pkg.price}` : "Custom Quote"}</p>
                <ul>
                  {pkg.features.map((feat, idx) => <li key={idx}>✓ {feat}</li>)}
                </ul>
              </div>
            ))}
          </div>
        </section>
      )}

      {activeLightbox && (
        <div className="lightbox-overlay" onClick={() => setActiveLightbox(null)}>
          <div className="lightbox-content">
            <button className="close-btn" onClick={() => setActiveLightbox(null)}>✕</button>
            <img
              src={getImagePath(activeLightbox.filename)}
              alt={activeLightbox.title}
              onError={(e) => {
                e.target.onerror = null;
                e.target.src = activeLightbox.fallbackSrc;
              }}
            />
          </div>
        </div>
      )}

      <footer className="footer">
        <p>© 2026 Shutter Stories Photography. All rights reserved.</p>
      </footer>
    </div>
  );
}
